INSERT INTO `notification_templates` VALUES
(1,1,1,NULL,'WA Tagihan Baru',NULL,'📢 *TAGIHAN IURAN BULANAN*\n\nHalo! Berikut adalah tagihan iuran Anda:\n\n🏠 *Rumah:* {{house_number}}\n👤 *Atas Nama:* {{nama_penghuni}}\n\n📋 *RINCIAN TAGIHAN:*\n{{bill_details}}\n\n─────────────────\n💰 *Total Tagihan:* {{amount}}\n\nMohon segera melakukan pembayaran. Terima kasih atas perhatian dan kerjasamanya. 🙏',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
(2,1,2,NULL,'Email Tagihan Baru','Tagihan Baru','<h2>📢 Tagihan Iuran Bulanan</h2>\n                <p>Halo! Berikut adalah tagihan iuran Anda:</p>\n\n                <table>\n                    <tr><td><strong>Rumah:</strong></td><td>{{house_number}}</td></tr>\n                    <tr><td><strong>Atas Nama:</strong></td><td>{{nama_penghuni}}</td></tr>\n                </table>\n\n                <h3>📋 Rincian Tagihan:</h3>\n                <pre>{{bill_details}}</pre>\n                <hr>\n                <p><strong>Total Tagihan: {{amount}}</strong></p>\n                <p>Mohon segera melakukan pembayaran. Terima kasih atas perhatian dan kerjasamanya. 🙏</p>',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
(3,2,1,NULL,'WA Pembayaran Berhasil',NULL,'✅ *KONFIRMASI PEMBAYARAN BERHASIL*\n\nTerima kasih telah melakukan pembayaran:\n\n🏠 *Rumah:* {{house_number}}\n👤 *Atas Nama:* {{nama_penghuni}}\n💳 *Jumlah:* {{amount}}\n👨‍💼 *Diterima oleh:* {{collector_name}}\n📅 *Tanggal:* {{payment_date}}\n\n📋 *RINCIAN PEMBAYARAN:*\n{{payment_details}}\n\n─────────────────\n💰 *Total:* {{amount}}\n\nPembayaran Anda telah tercatat dengan baik. Terima kasih! 🎉',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
(4,2,2,NULL,'Email Pembayaran Berhasil','Konfirmasi Pembayaran Berhasil','<h2>✅ Konfirmasi Pembayaran Berhasil</h2>\n            <p>Terima kasih telah melakukan pembayaran:</p>\n            <table>\n                <tr><td><strong>Rumah:</strong></td><td>{{house_number}}</td></tr>\n                <tr><td><strong>Atas Nama:</strong></td><td>{{nama_penghuni}}</td></tr>\n                <tr><td><strong>Jumlah:</strong></td><td>{{amount}}</td></tr>\n                <tr><td><strong>Diterima oleh:</strong></td><td>{{collector_name}}</td></tr>\n                <tr><td><strong>Tanggal:</strong></td><td>{{payment_date}}</td></tr>\n            </table>\n\n            <h3>📋 Rincian Pembayaran:</h3>\n            {{payment_details}}\n            <hr>\n            <p><strong>Total: {{amount}}</strong></p>\n            <p>Pembayaran Anda telah tercatat dengan baik. Terima kasih!</p>',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
(5,3,1,NULL,'WA Perubahan Pembayaran',NULL,'🔁 *PEMBAYARAN DIPERBARUI*\n\nPembayaran Anda telah diperbarui oleh pengurus:\n\n🏠 *Rumah:* {{house_number}}\n👤 *Atas Nama:* {{nama_penghuni}}\n💳 *Jumlah Baru:* {{amount}}\n📅 *Tanggal:* {{payment_date}}\n\n📋 *RINCIAN PEMBAYARAN:*\n{{payment_details}}\n\n📝 *Status Terbaru:* {{status}}\n\n🧑‍💼 *Diperbarui oleh:* {{updated_by}}\n\nJika ada pertanyaan, silakan hubungi pengurus RT. Terima kasih.',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
(6,3,2,NULL,'Email Perubahan Pembayaran','Perubahan Pembayaran','\n                    <h2>🔁 Perubahan Pembayaran</h2>\n                    <p>Pembayaran Anda telah diperbarui oleh pengurus:</p>\n                    <table>\n                        <tr><td><strong>Rumah:</strong></td><td>{{house_number}}</td></tr>\n                        <tr><td><strong>Atas Nama:</strong></td><td>{{nama_penghuni}}</td></tr>\n                        <tr><td><strong>Jumlah Baru:</strong></td><td>{{amount}}</td></tr>\n                        <tr><td><strong>Tanggal:</strong></td><td>{{payment_date}}</td></tr>\n                        <tr><td><strong>Status Terbaru:</strong></td><td>{{status}}</td></tr>\n                        <tr><td><strong>Diperbarui oleh:</strong></td><td>{{updated_by}}</td></tr>\n                    </table>\n                    <h3>📋 Rincian Pembayaran:</h3>\n                    <pre>{{payment_details}}</pre>\n                    <p>Jika ada pertanyaan, silakan hubungi pengurus RT. Terima kasih.</p>',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
(7,4,1,NULL,'WA Pembayaran Gagal',NULL,'Halo {{name}}, pembayaran sebesar {{amount}} gagal diproses. Silakan coba lagi atau hubungi admin.',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
(8,4,2,NULL,'Email Pembayaran Gagal','Pembayaran Gagal','Yth. {{name}}, pembayaran sebesar {{amount}} gagal diproses. Silakan coba lagi atau hubungi admin.',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
(9,5,1,NULL,'WA Menunggu Pembayaran Gateway',NULL,'Halo {{name}}, tagihan sebesar {{amount}} sedang menunggu pembayaran melalui {{gateway}}. Mohon selesaikan sebelum {{due_date}}.',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
