(11,6,1,NULL,'WA Pembayaran Gateway Berhasil',NULL,'Terima kasih {{name}}, pembayaran sebesar {{amount}} melalui {{gateway}} telah berhasil pada {{date}}.',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
(12,6,2,NULL,'Email Pembayaran Gateway Berhasil','Pembayaran Berhasil','Halo {{name}}, pembayaran Anda sebesar {{amount}} melalui {{gateway}} berhasil pada {{date}}.',1,'2026-01-01 03:43:22','2026-01-01 03:43:22'),
